import { memo, useMemo } from "react";
import type { TextOverlayProps } from "./types";

type Position = NonNullable<TextOverlayProps["position"]>;

interface BlurVignetteProps {
  opacity: number;
  position: Position;
  maxBlur?: number;
}

// Position offsets for the gradient center
const positionOffsets: Record<Position, { x: string; y: string }> = {
  center: { x: "50%", y: "50%" },
  "top-center": { x: "50%", y: "25%" },
  left: { x: "20%", y: "50%" },
  right: { x: "80%", y: "50%" },
  "bottom-left": { x: "25%", y: "75%" },
  "bottom-right": { x: "75%", y: "75%" },
};

export const BlurVignette = memo(function BlurVignette({
  opacity,
  position,
}: BlurVignetteProps) {
  // Round opacity to reduce re-renders
  const roundedOpacity = Math.round(opacity * 50) / 50;

  const style = useMemo((): React.CSSProperties => {
    const { x, y } = positionOffsets[position];

    return {
      position: "absolute",
      inset: 0,
      pointerEvents: "none",
      zIndex: 5,
      // Simple radial gradient instead of expensive backdrop-filter blur
      background: `radial-gradient(
        ellipse 60% 50% at ${x} ${y},
        rgba(0, 0, 0, 0.7) 0%,
        rgba(0, 0, 0, 0.4) 40%,
        transparent 70%
      )`,
      opacity: roundedOpacity,
    };
  }, [position, roundedOpacity]);

  if (roundedOpacity < 0.02) return null;

  return <div style={style} />;
}, (prevProps, nextProps) => {
  const prevOpacity = Math.round(prevProps.opacity * 50) / 50;
  const nextOpacity = Math.round(nextProps.opacity * 50) / 50;
  return prevProps.position === nextProps.position && prevOpacity === nextOpacity;
});

export const FRAME_COUNT = 120;
export const FRAME_PATH = "/frames/ezgif-frame-";
