"use client";

import React, { ReactNode, useMemo, memo } from "react";

interface WindTextProps {
  children: ReactNode;
  mode: "in" | "out" | "visible" | "hidden";
  progress: number;
}

// Smoothstep easing
const ease = (t: number) => t * t * (3 - 2 * t);

export const WindText = memo(function WindText({ children, mode, progress }: WindTextProps) {
  const style = useMemo((): React.CSSProperties => {
    const baseStyle: React.CSSProperties = {
      display: "block",
      willChange: mode === "in" || mode === "out" ? "opacity, transform" : "auto",
    };

    if (mode === "visible") {
      return {
        ...baseStyle,
        opacity: 1,
        transform: "translate3d(0, 0, 0)",
      };
    }

    if (mode === "hidden") {
      return {
        ...baseStyle,
        opacity: 0,
        visibility: "hidden",
      };
    }

    const smoothP = ease(progress);

    if (mode === "in") {
      const inv = 1 - smoothP;
      return {
        ...baseStyle,
        opacity: smoothP,
        transform: `translate3d(${-15 * inv}px, ${5 * inv}px, 0)`,
      };
    }

    if (mode === "out") {
      return {
        ...baseStyle,
        opacity: 1 - smoothP,
        transform: `translate3d(${20 * smoothP}px, ${-5 * smoothP}px, 0)`,
      };
    }

    return baseStyle;
  }, [mode, progress]);

  return <div style={style}>{children}</div>;
}, (prevProps, nextProps) => {
  if (prevProps.mode !== nextProps.mode) return false;

  // For static modes, no need to re-render
  if (nextProps.mode === "visible" || nextProps.mode === "hidden") {
    return true;
  }

  // For animating modes, only re-render on significant progress change
  return Math.abs(prevProps.progress - nextProps.progress) < 0.02;
});

