import { FRAME_COUNT, FRAME_PATH, FRAME_EXT } from "./constants";

// Preload and pre-decode all images for smooth canvas rendering
export const preloadImages = async (
  onProgress: (progress: number) => void
): Promise<HTMLImageElement[]> => {
  const images: HTMLImageElement[] = [];
  let loaded = 0;

  const loadPromises = Array.from({ length: FRAME_COUNT }, async (_, i) => {
    const frameNumber = String(i + 1).padStart(3, "0");
    const src = `${FRAME_PATH}${frameNumber}${FRAME_EXT}`;

    // Fetch as blob for better control
    const response = await fetch(src);
    const blob = await response.blob();

    // Create image element
    const img = new Image();
    img.src = URL.createObjectURL(blob);

    // Wait for load
    await new Promise<void>((resolve, reject) => {
      img.onload = () => resolve();
      img.onerror = reject;
    });

    // Pre-decode the image for canvas rendering
    // This prevents jank when first drawing each frame
    if (img.decode) {
      try {
        await img.decode();
      } catch {
        // Decode failed, image will decode on first draw (fallback)
      }
    }

    loaded++;
    onProgress((loaded / FRAME_COUNT) * 100);

    return { img, index: i };
  });

  const results = await Promise.all(loadPromises);
  results.forEach(({ img, index }) => {
    images[index] = img;
  });

  return images;
};

