"use client";

import { useEffect, useRef, useState, useCallback } from "react";
import { useScroll, useTransform } from "framer-motion";

import { FRAME_COUNT } from "./constants";
import { preloadImages } from "./utils";
import { LoadingScreen } from "./LoadingScreen";
import { Navigation } from "./Navigation";
import { ScrollIndicator } from "./ScrollIndicator";
import {
  HeroSection,
  WeightlessSection,
  WaveguideSection,
  NeuralSection,
  CTASection,
} from "./sections";

export default function GlassesScroll() {
  const containerRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [images, setImages] = useState<HTMLImageElement[]>([]);
  const [loadingProgress, setLoadingProgress] = useState(0);
  const [isLoaded, setIsLoaded] = useState(false);
  const [currentProgress, setCurrentProgress] = useState(0);

  // Refs for throttling
  const lastFrameRef = useRef(-1);
  const rafIdRef = useRef<number | null>(null);
  const lastStateUpdateRef = useRef(0);
  const pendingProgressRef = useRef(0);
  const hasInitializedRef = useRef(false);
  const lastProgressRef = useRef(0);

  // Cache canvas context and dimensions
  const canvasCtxRef = useRef<CanvasRenderingContext2D | null>(null);
  const canvasDimensionsRef = useRef({ width: 0, height: 0, dpr: 1 });

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"],
  });

  // Use transform instead of spring for lighter weight
  const smoothProgress = useTransform(scrollYProgress, [0, 1], [0, 1], {
    ease: (t) => {
      // Custom easing for smooth feel without spring overhead
      return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
    },
  });

  // Load images on mount
  useEffect(() => {
    preloadImages((progress) => {
      setLoadingProgress(progress);
    }).then((loadedImages) => {
      setImages(loadedImages);
      setIsLoaded(true);
    });
  }, []);

  // Setup canvas once
  const setupCanvas = useCallback(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const viewportWidth = window.innerWidth;
    const viewportHeight = window.innerHeight;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    canvas.width = viewportWidth * dpr;
    canvas.height = viewportHeight * dpr;
    canvas.style.width = `${viewportWidth}px`;
    canvas.style.height = `${viewportHeight}px`;

    // Cache context
    canvasCtxRef.current = canvas.getContext("2d", { alpha: false });
    canvasDimensionsRef.current = { width: viewportWidth, height: viewportHeight, dpr };
  }, []);

  // Draw frame - minimal work
  const drawFrame = useCallback(
    (frameIndex: number) => {
      const ctx = canvasCtxRef.current;
      if (!ctx || images.length === 0) return;

      if (frameIndex === lastFrameRef.current) return;
      lastFrameRef.current = frameIndex;

      const img = images[frameIndex];
      if (!img) return;

      const { width: vw, height: vh, dpr } = canvasDimensionsRef.current;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

      const imgRatio = img.width / img.height;
      const canvasRatio = vw / vh;

      let dw, dh, dx, dy;
      if (imgRatio > canvasRatio) {
        dh = vh;
        dw = vh * imgRatio;
        dx = (vw - dw) / 2;
        dy = 0;
      } else {
        dw = vw;
        dh = vw / imgRatio;
        dx = 0;
        dy = (vh - dh) / 2;
      }

      ctx.drawImage(img, dx, dy, dw, dh);
    },
    [images]
  );

  // Optimized scroll handler with velocity-based frame skipping
  const handleProgress = useCallback((progress: number) => {
    // Chrome sometimes fires with wrong initial value - ignore large jumps on first frame
    if (!hasInitializedRef.current) {
      hasInitializedRef.current = true;
      if (progress > 0.1) {
        return;
      }
    }

    pendingProgressRef.current = progress;

    if (rafIdRef.current !== null) return;

    rafIdRef.current = requestAnimationFrame(() => {
      rafIdRef.current = null;
      const currentProg = pendingProgressRef.current;

      // Calculate scroll velocity
      const velocity = Math.abs(currentProg - lastProgressRef.current);
      lastProgressRef.current = currentProg;

      // For very fast scrolling, we can be less precise with frame updates
      // This reduces canvas draw calls during rapid scroll
      let frameIndex = Math.min(
        Math.floor(currentProg * FRAME_COUNT),
        FRAME_COUNT - 1
      );

      // Skip odd frames during fast scroll (velocity > 2% per frame)
      if (velocity > 0.02 && frameIndex % 2 === 1) {
        frameIndex = Math.max(0, frameIndex - 1);
      }

      drawFrame(frameIndex);

      // Throttle React state updates to ~20fps (every 50ms)
      const now = performance.now();
      if (now - lastStateUpdateRef.current > 50) {
        lastStateUpdateRef.current = now;
        setCurrentProgress(currentProg);
      }
    });
  }, [drawFrame]);

  // Subscribe to scroll
  useEffect(() => {
    if (!isLoaded) return;

    setupCanvas();
    hasInitializedRef.current = false; // Reset for fresh start
    drawFrame(0); // Draw initial frame

    const unsubscribe = smoothProgress.on("change", handleProgress);

    return () => {
      unsubscribe();
      if (rafIdRef.current !== null) {
        cancelAnimationFrame(rafIdRef.current);
      }
    };
  }, [isLoaded, smoothProgress, drawFrame, setupCanvas, handleProgress]);

  // Handle resize
  useEffect(() => {
    if (!isLoaded) return;

    const handleResize = () => {
      setupCanvas();
      lastFrameRef.current = -1;
      const frameIndex = Math.min(
        Math.floor(currentProgress * FRAME_COUNT),
        FRAME_COUNT - 1
      );
      drawFrame(frameIndex);
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [isLoaded, currentProgress, drawFrame, setupCanvas]);

  return (
    <div
      ref={containerRef}
      style={{
        position: "relative",
        height: "500vh",
        backgroundColor: "#0a0a0b",
      }}
    >
      <div
        style={{
          position: "sticky",
          top: 0,
          left: 0,
          width: "100%",
          height: "100vh",
          overflow: "hidden",
          contain: "layout style paint",
          willChange: "transform",
        }}
      >
        {!isLoaded && <LoadingScreen progress={loadingProgress} />}

        <canvas
          ref={canvasRef}
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: "100%",
            height: "100%",
            opacity: isLoaded ? 1 : 0,
            contain: "strict",
          }}
        />

        {isLoaded && <Navigation />}

        {/* Only render sections near current progress to reduce DOM work */}
        {isLoaded && currentProgress < 0.25 && (
          <HeroSection scrollProgress={currentProgress} />
        )}
        {isLoaded && currentProgress >= 0.2 && currentProgress < 0.5 && (
          <WeightlessSection scrollProgress={currentProgress} />
        )}
        {isLoaded && currentProgress >= 0.4 && currentProgress < 0.7 && (
          <WaveguideSection scrollProgress={currentProgress} />
        )}
        {isLoaded && currentProgress >= 0.6 && currentProgress < 0.9 && (
          <NeuralSection scrollProgress={currentProgress} />
        )}
        {isLoaded && currentProgress >= 0.8 && (
          <CTASection scrollProgress={currentProgress} />
        )}

        {isLoaded && <ScrollIndicator visible={currentProgress < 0.1} />}
      </div>
    </div>
  );
}

import { memo } from "react";
