export const TextOverlay = memo(function TextOverlay({
  children,
  scrollProgress,
  showRange,
  position = "center",
  blurEnabled = true,
  blurIntensity = 20,
  skipFadeIn = false,
  skipFadeOut = false,
}: TextOverlayProps) {
  const [start, end] = showRange;

  // Early exit: completely outside range with no skip flags
  if (scrollProgress < start - 0.01 && !skipFadeIn) return null;
  if (scrollProgress > end + 0.01 && !skipFadeOut) return null;

  const fadeInEnd = start + 0.05;
  const fadeOutStart = end - 0.05;

  let opacity = 0;
  let mode: "in" | "out" | "visible" | "hidden" = "hidden";
  let windProgress = 0;

  // Determine state
  if (scrollProgress < start) {
    if (skipFadeIn) {
      opacity = 1;
      mode = "visible";
      windProgress = 1;
    } else {
      opacity = 0;
      mode = "hidden";
      windProgress = 0;
    }
  } else if (scrollProgress > end) {
    if (skipFadeOut) {
      opacity = 1;
      mode = "visible";
      windProgress = 1;
    } else {
      opacity = 0;
      mode = "hidden";
      windProgress = 0;
    }
  } else {
    // Inside range [start, end]
    if (!skipFadeIn && scrollProgress < fadeInEnd) {
      // FADE IN
      opacity = (scrollProgress - start) / (fadeInEnd - start);
      mode = "in";
      windProgress = opacity;
    } else if (!skipFadeOut && scrollProgress > fadeOutStart) {
      // FADE OUT
      const outP = (scrollProgress - fadeOutStart) / (end - fadeOutStart);
      opacity = 1 - outP;
      mode = "out";
      windProgress = outP;
    } else {
      // FULLY VISIBLE
      opacity = 1;
      mode = "visible";
      windProgress = 1;
    }
  }

  // Don't render if hidden
  if (mode === "hidden" && opacity < 0.01) return null;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        pointerEvents: "none",
      }}
    >
      {/* Blur vignette backdrop */}
      {blurEnabled && opacity > 0.01 && (
        <BlurVignette
          opacity={opacity}
          position={position}
          maxBlur={blurIntensity}
        />
      )}

      {/* Text content */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          zIndex: 10,
          opacity: mode === "hidden" ? 0 : 1,
          ...positionStyles[position],
        }}
      >
        <WindText mode={mode} progress={windProgress}>
          {children}
        </WindText>
      </div>
    </div>
  );
});

